const caseStudyOrder = ["century-expeditions", "ubannest", "tanzania-soccer-hub", "slcms", "sacred-heart-secondary-school"];
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

function escapeHtml(value) {
  const node = document.createElement("span");
  node.textContent = value == null ? "" : String(value);
  return node.innerHTML;
}

function applyTheme(theme) {
  const next = theme === "dark" ? "dark" : "light";
  document.documentElement.dataset.theme = next;
  try { localStorage.setItem("kai10-theme", next); } catch (_) {}
  $$('[data-theme-toggle]').forEach((button) => {
    const dark = next === "dark";
    button.setAttribute("aria-pressed", String(dark));
    button.setAttribute("aria-label", dark ? "Switch to light mode" : "Switch to dark mode");
  });
}

function initTheme() {
  let saved = null;
  try { saved = localStorage.getItem("kai10-theme"); } catch (_) {}
  applyTheme(saved || "light");
  $$('[data-theme-toggle]').forEach((button) => button.addEventListener("click", () => applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark")));
}

function initMenu() {
  const toggle = $('[data-menu-toggle]');
  const menu = $('#mobile-menu');
  if (!toggle || !menu) return;
  const close = () => { toggle.setAttribute("aria-expanded", "false"); toggle.setAttribute("aria-label", "Open menu"); menu.hidden = true; };
  toggle.addEventListener("click", () => { const open = toggle.getAttribute("aria-expanded") === "true"; toggle.setAttribute("aria-expanded", String(!open)); toggle.setAttribute("aria-label", open ? "Open menu" : "Close menu"); menu.hidden = open; });
  $$('a, button', menu).forEach((item) => item.addEventListener("click", close));
}

function initReveal() {
  const autoRevealSelectors = [
    "main > *",
    ".about-note",
    ".focus-card",
    ".value-card",
    ".service-card",
    ".next-step",
    ".portfolio-card",
    ".project-card",
    ".work-row",
    "footer.site-footer"
  ];
  autoRevealSelectors.forEach((selector) => $$(selector).forEach((element) => element.classList.add("reveal")));
  const items = $$(".reveal");
  if (!items.length) return;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reducedMotion || !("IntersectionObserver" in window)) {
    items.forEach((item) => item.classList.add("is-visible"));
    return;
  }
  document.documentElement.classList.add("reveal-ready");
  const observer = new IntersectionObserver((entries, observerRef) => entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add("is-visible");
      observerRef.unobserve(entry.target);
    }
  }), { threshold: .12, rootMargin: "0px 0px -5%" });
  items.forEach((item) => observer.observe(item));
}
function projectKeyFromHref(href) {
  const query = href.match(/[?&]project=([^&]+)/);
  if (query && projectRecords[query[1]]) return query[1];
  return caseStudyOrder.find((key) => href.includes(`${key}.html`)) || null;
}

function projectUrl(key) {
  const isRootPage = !window.location.pathname.includes("/dist/");
  return `${isRootPage ? "dist/" : ""}projects/case-study.html?project=${key}`;
}

function syncProjectDirectory() {
  $$('[data-project-card]').forEach((card) => {
    const detailLink = $('.view-project', card);
    const key = detailLink ? projectKeyFromHref(detailLink.getAttribute("href") || "") : null;
    const project = key && projectRecords[key];
    if (!project) return;
    card.dataset.projectKey = key;
    const art = $('.portfolio-art', card);
    if (art) { art.href = projectUrl(key); art.removeAttribute("target"); art.setAttribute("aria-label", `Read the ${project.title} case study`); }
    if (detailLink) detailLink.href = projectUrl(key);
    const title = $('.portfolio-info h2', card);
    const category = $('.portfolio-info h2 + p', card);
    const description = $('.portfolio-info > p', card);
    if (title) title.textContent = project.title;
    if (category) category.textContent = project.category;
    if (description) description.textContent = project.intro;
  });

  $$('a[href*="projects/"]').forEach((link) => {
    const href = link.getAttribute("href") || "";
    const key = projectKeyFromHref(href);
    if (key && !link.classList.contains("live-project")) link.href = href.includes("../") ? `../${projectUrl(key)}` : projectUrl(key);
  });

  $$('[alt], [aria-label]').forEach((element) => ["alt", "aria-label"].forEach((attribute) => {
    const value = element.getAttribute(attribute);
    if (value && value.includes("Ubannest")) element.setAttribute(attribute, value.replaceAll("Ubannest", "UrbanNest"));
  }));
  $$('h1, h2, h3, strong, b, small, span').forEach((element) => { if (!element.childElementCount && element.textContent.trim() === "Ubannest") element.textContent = "UrbanNest"; });
}

function renderCaseStudy() {
  const root = $('[data-project-root]');
  if (!root) return;
  const key = root.dataset.project || new URLSearchParams(window.location.search).get("project") || "century-expeditions";
  const project = projectRecords[key] || projectRecords[caseStudyOrder[0]];
  root.dataset.project = key;
  document.title = `${project.title} - Kai10`;
  const description = $('meta[name="description"]');
  if (description) description.content = `${project.title} project case study from Kai10.`;
  const setText = (selector, value) => $$(selector).forEach((element) => { element.textContent = value || ""; });
  setText('[data-project-title]', project.title);
  setText('[data-project-category]', project.category);
  setText('[data-project-intro]', project.intro);
  setText('[data-project-overview]', project.overview);
  setText('[data-project-aim]', project.aim);
  setText('[data-project-target-users]', project.targetUsers);
  setText('[data-project-location]', project.location);
  setText('[data-project-problem]', project.problem);
  setText('[data-project-contribution]', project.contribution);
  setText('[data-project-status]', project.status);
  setText('[data-project-stack]', project.stack);
  setText('[data-project-lessons]', project.lessons);
  setText('[data-project-walkthrough-note]', project.walkthrough);

  const completion = $('[data-project-completion]');
  if (completion) { completion.hidden = !project.completionDate; setText('[data-project-completion-value]', project.completionDate); }
  const hero = $('[data-project-art]');
  if (hero) hero.innerHTML = `<figure class="case-hero-preview"><img src="${escapeHtml(project.image)}" alt="${escapeHtml(project.imageAlt)}" /><figcaption>${escapeHtml(project.screenshotCaption)}</figcaption></figure>`;

  setText('[data-project-status-designed]', project.statusDetail.designed);
  setText('[data-project-status-implemented]', project.statusDetail.implemented);
  setText('[data-project-status-planned]', project.statusDetail.planned);

  const featureList = $('[data-project-features]');
  if (featureList) featureList.innerHTML = project.features.map((feature, index) => {
    const planned = feature[2] === "planned";
    return `<article class="case-feature"><span class="feature-number">${String(index + 1).padStart(2, "0")}</span><div><div class="case-feature-heading"><h3>${escapeHtml(feature[0])}</h3><span class="feature-status ${planned ? "is-planned" : "is-working"}">${planned ? "Planned" : "Working preview"}</span></div><p>${escapeHtml(feature[1])}</p></div></article>`;
  }).join("");

  const gallery = $('[data-project-gallery]');
  if (gallery) gallery.innerHTML = project.gallery.map((item, index) => `<figure class="screenshot-card ${index === 0 ? "screenshot-primary" : ""}"><button class="screenshot-button" type="button" data-screenshot-open data-screenshot-index="${index}" aria-label="Open ${escapeHtml(item.title)} screenshot"><img src="${escapeHtml(project.image)}" alt="${escapeHtml(project.imageAlt)}" /></button><figcaption><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.caption)}</span></figcaption></figure>`).join("");

  const walkthroughImage = $('[data-project-walkthrough-image]');
  if (walkthroughImage) { walkthroughImage.src = project.image; walkthroughImage.alt = project.imageAlt; }
  $$('[data-live-project], [data-project-link-live]').forEach((link) => { link.href = project.liveUrl; link.target = "_blank"; link.rel = "noopener noreferrer"; });
  const source = $('[data-project-source-link]');
  if (source) { source.hidden = !project.sourceUrl; if (project.sourceUrl) { source.href = project.sourceUrl; source.target = "_blank"; source.rel = "noopener noreferrer"; } }
  const demo = $('[data-project-demo-link]');
  if (demo) { demo.hidden = !project.demoUrl; if (project.demoUrl) { demo.href = project.demoUrl; demo.target = "_blank"; demo.rel = "noopener noreferrer"; } }
  const demoNote = $('[data-project-demo-note]');
  if (demoNote) demoNote.hidden = Boolean(project.demoUrl);
  const demoSection = $('[data-project-demo-section]');
  if (demoSection) { demoSection.hidden = !project.demoUrl; if (project.demoUrl) { const video = $('video', demoSection); if (video) video.src = project.demoUrl; } }

  const nextKey = caseStudyOrder[(caseStudyOrder.indexOf(key) + 1) % caseStudyOrder.length];
  const next = projectRecords[nextKey];
  const nextLink = $('[data-project-next-link]');
  if (nextLink && next) { nextLink.href = `case-study.html?project=${nextKey}`; nextLink.setAttribute("aria-label", `Next project: ${next.title}`); }
  setText('[data-project-next-title]', next ? next.title : "Next project");
  setText('[data-project-next-label]', next ? "Next Project" : "View next project");

  initGallery(project);
}

function initGallery(project) {
  const buttons = $$('[data-screenshot-open]');
  if (!buttons.length) return;
  let active = 0;
  const dialog = document.createElement("dialog");
  dialog.className = "screenshot-dialog";
  dialog.innerHTML = `<button type="button" class="dialog-close" aria-label="Close screenshot">Close</button><button type="button" class="dialog-nav dialog-prev" aria-label="Previous screenshot">‹</button><img alt="" /><button type="button" class="dialog-nav dialog-next" aria-label="Next screenshot">›</button><p class="dialog-caption"></p>`;
  document.body.appendChild(dialog);
  const image = $('img', dialog); const caption = $('.dialog-caption', dialog);
  const update = () => { const item = project.gallery[active] || project.gallery[0]; image.src = project.image; image.alt = project.imageAlt; caption.textContent = item ? `${item.title} — ${item.caption}` : ""; };
  const close = () => dialog.close();
  buttons.forEach((button) => button.addEventListener("click", () => { active = Number(button.dataset.screenshotIndex) || 0; update(); dialog.showModal(); }));
  $('.dialog-close', dialog).addEventListener("click", close);
  $('.dialog-prev', dialog).addEventListener("click", () => { active = (active - 1 + project.gallery.length) % project.gallery.length; update(); });
  $('.dialog-next', dialog).addEventListener("click", () => { active = (active + 1) % project.gallery.length; update(); });
  dialog.addEventListener("click", (event) => { if (event.target === dialog) close(); });
}

function initProjectDirectory() {
  const cards = $$('[data-project-card]');
  const filters = $$('[data-project-filter]');
  const search = $('[data-project-search]');
  const count = $('[data-project-count]');
  const empty = $('[data-project-empty]');
  if (!cards.length || !filters.length || !count) return;
  let active = "all";
  const update = () => {
    const query = search ? search.value.trim().toLowerCase() : "";
    let visible = 0;
    cards.forEach((card) => { const matchesFilter = active === "all" || card.dataset.category === active; const matchesSearch = !query || (card.dataset.search || "").toLowerCase().includes(query); const show = matchesFilter && matchesSearch; card.hidden = !show; if (show) visible += 1; });
    count.textContent = `${visible} ${visible === 1 ? "project" : "projects"}`;
    if (empty) empty.hidden = visible !== 0;
  };
  filters.forEach((filter) => filter.addEventListener("click", () => { active = filter.dataset.projectFilter || "all"; filters.forEach((item) => { const selected = item === filter; item.classList.toggle("is-active", selected); item.setAttribute("aria-pressed", String(selected)); }); update(); }));
  if (search) search.addEventListener("input", update);
  update();
}

document.addEventListener("DOMContentLoaded", () => {
  initTheme();
  initMenu();
  syncProjectDirectory();
  renderCaseStudy();
  initReveal();
  initProjectDirectory();
  $$('[data-year]').forEach((element) => { element.textContent = new Date().getFullYear(); });
});
